export const appLocale=()=>i18n.language==='hi'?'hi-IN':'en-IN';
export const trDynamic=(value:string)=>{
  const text=String(value??'');
  if(i18n.language!=='hi') return text;
  const exact=hi[text];
  if(exact) return exact;
  const amount=text.match(/^(.+?)\s+(₹[\d,]+(?:\.\d{1,2})?)\.$/);
  if(amount) return `${tr(amount[1])} ${amount[2]}.`;
  return hi[text] ?? hiFallback(text);
};

